(()=>{const s=localStorage,p=Storage.prototype,rows=[],keys=()=>Array.from({length:s.length},(_,i)=>p.key.call(s,i));for(const[group,list]of[['alphabet',['a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t']],['numbers',['5','1','0','01','2','4294967295','4294967294','-1','1.5','NaN']],['words',['zero','one','two','ordinary','getItem','length','named','physical','constructor','toString','key','removeItem']],['unicode',['','é','🐼','中','\ud800','a\0b','A','aa','aaa','aaaa']]]){p.clear.call(s);for(const name of list){p.setItem.call(s,name,name);rows.push({group,operation:'insert',name,keys:keys(),own:Object.keys(s),ownRaw:Reflect.ownKeys(s).map(String)})}for(const name of list.filter((_,i)=>i%2===0)){p.removeItem.call(s,name);rows.push({group,operation:'delete',name,keys:keys()})}for(const name of list.filter((_,i)=>i%2===0)){p.setItem.call(s,name,'again');rows.push({group,operation:'reinsert',name,keys:keys()})}p.clear.call(s);p.setItem.call(s,'zero','0');p.setItem.call(s,'one','1');rows.push({group,operation:'after-clear',keys:keys()});}return rows;})()
